export
const
getJSONCompletion
=
async
<
T
>(
options
:
[
Omit<
ChatCompletionParseParams
,
'
model
'
>
&
{ model:
Model
},
Omit<
ChatCompletionParseParams
,
'
model
'
>
&
{ model:
Model
},
],
)
:
Promise<
ParsedChatCompletion
<
T>
&
{ _request_id?:
string
|
null
|
undefined
}
>
=>
{
try
{
const
isGemini
=
options[
0
].model.includes(
'gemini'
);
const
openai
=
new
OpenAI(
isGemini
?
{
apiKey:
process.env.GEMINI_API_KEY
,
baseURL
:
'https://generativelanguage.googleapis.com/v1beta/openai/'
,
}
:
{ apiKey:
process.env.OPENAI_API_KEY
},
);
return
await
openai.beta.chat.completions.parse({ ...options[
0
] });
}
catch
(error) {
console.log(
'Failed completion for first model'
, error);
const
isGemini
=
options[
1
].model.includes(
'gemini'
);
const
openai
=
new
OpenAI(
isGemini
?
{
apiKey:
process.env.GEMINI_API_KEY
,
baseURL
:
'https://generativelanguage.googleapis.com/v1beta/openai/'
,
}
:
{ apiKey:
process.env.OPENAI_API_KEY
},
);
return
await
openai.beta.chat.completions.parse({ ...options[
1
] });
}
};
It can be used in the following way:
import
z
from
'zod'
;
//... Omitted for brevity
const
messages
=
[{ role
:
"user"
, content
:
"Your instructions..."
}] satisfies ChatCompletionMessageParam[];
const
format
=
z.
object
({ customizations:
z.array
(z.
string
()) });
const
responseFormat
=
zodResponseFormat(format,
'chart-customizations'
);
const
completion
=
await
getJSONCompletion<
z.infer
<
typeof format>
>
(
[
{ model
:
'gemini-2.5-pro-exp-03-25'
, response_format:
responseFormat
, messages, temperature:
0
},
{ model
:
'o3-mini-2025-01-31'
, reasoning_effort
:
'high'
, response_format:
responseFormat
, messages },
],
);
const
customizationsArr
=
completion.choices[
0
].message.parsed
?
